#include <bits/stdc++.h>
using namespace std;

// Decode UTF-8 into code points so positions match the problem's character indices.
static vector<int> codepoints(const string &s) {
    vector<int> out;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = s[i];
        int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
        int cp = len == 1 ? c : c & (0xFF >> (len + 1));
        for (int k = 1; k < len && i + k < s.size(); k++) cp = cp << 6 | (s[i + k] & 0x3F);
        out.push_back(cp);
        i += len;
    }
    return out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string rs, rt;
    cin >> rs >> rt;
    vector<int> s = codepoints(rs), t = codepoints(rt);
    int n = s.size();
    vector<int> when(n, 0);  // deletion step of each position
    for (int step = 1; step <= n; step++) {
        int p;
        cin >> p;
        when[p - 1] = step;
    }
    // Greedy subsequence check after the first `count` deletions.
    auto works = [&](int count) {
        size_t j = 0;
        for (int i = 0; i < n; i++)
            if (when[i] > count && s[i] == t[j] && ++j == t.size()) return true;
        return false;
    };
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (works(mid)) lo = mid;
        else hi = mid - 1;
    }
    printf("%d\n", lo);
}

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int n;
    static int[] s, t, when;

    // Greedy subsequence check after the first `count` deletions.
    static boolean works(int count) {
        int j = 0;
        for (int i = 0; i < n; i++)
            if (when[i] > count && s[i] == t[j] && ++j == t.length) return true;
        return false;
    }

    static int[] word() {
        skip();
        int a = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        // Code points, so positions match the problem's character indices.
        return new String(buf, a, pos - a, StandardCharsets.UTF_8).codePoints().toArray();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        s = word();
        t = word();
        n = s.length;
        when = new int[n]; // deletion step of each position
        for (int step = 1; step <= n; step++) when[nextInt() - 1] = step;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (works(mid)) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}

